const { useEffect, useRef, useState } = React;

const DURATION_MS = 12000;
const ITEMS = [
  { label: "React", className: "bg-tag-1-soft text-tag-1" },
  { label: "Vue", className: "bg-tag-2-soft text-tag-2" },
  { label: "Svelte", className: "bg-tag-3-soft text-tag-3" },
  { label: "Angular", className: "bg-tag-4-soft text-tag-4" },
  { label: "Solid", className: "bg-tag-5-soft text-tag-5" },
  { label: "Astro", className: "bg-accent-soft text-accent-text" },
];
// 内容复制一份，translateX(-50%) 恰好滚过一份的宽度，首尾无缝衔接
const TRACK = [...ITEMS, ...ITEMS];

const Component = () => {
  const trackRef = useRef(null);
  const frameRef = useRef(0);
  const [hovered, setHovered] = useState(false);
  const [pauseOnHover, setPauseOnHover] = useState(true);
  const [forcePaused, setForcePaused] = useState(false);
  const [progress, setProgress] = useState(0);
  const paused = forcePaused || (pauseOnHover && hovered);

  // 逐帧读取动画进度：暂停时 currentTime 停住，恢复后从原处继续
  useEffect(() => {
    const tick = () => {
      const animation = trackRef.current?.getAnimations?.()[0];
      if (animation) setProgress(((Number(animation.currentTime) || 0) % DURATION_MS) / DURATION_MS);
      frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameRef.current);
  }, []);

  return (
    <div className="flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-track {
            animation: cb-marquee ${DURATION_MS}ms linear infinite;
          }
          .cb-track[data-paused="true"] { animation-play-state: paused; }
          .cb-viewport {
            mask: linear-gradient(90deg, transparent, var(--tau-ink-1) 8%, var(--tau-ink-1) 92%, transparent);
          }
        }
        @keyframes cb-marquee {
          from { transform: translateX(0); }
          to { transform: translateX(-50%); }
        }
      `}</style>
      <div
        onPointerEnter={() => setHovered(true)}
        onPointerLeave={() => setHovered(false)}
        className={`rounded-tau-md border py-4 transition-colors ${paused ? "border-accent" : "border-line-1"}`}
      >
        <div className="cb-viewport overflow-hidden">
          <div ref={trackRef} data-paused={paused} className="cb-track flex w-max">
            {TRACK.map((item, index) => (
              <div
                key={index}
                className={`mr-3 flex h-16 w-28 shrink-0 items-center justify-center rounded-tau-sm text-tau-body ${item.className}`}
              >
                {item.label}
              </div>
            ))}
          </div>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button
          variant="secondary"
          size="sm"
          icon={forcePaused ? icons.Play : icons.Pause}
          onClick={() => setForcePaused(value => !value)}
        >
          {forcePaused ? "继续" : "暂停"}
        </ui.Button>
        <ui.Switch checked={pauseOnHover} onCheckedChange={setPauseOnHover} label="悬停时暂停" size="sm" />
        <code className="ml-auto rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
          animation-play-state: {paused ? "paused" : "running"}
        </code>
      </div>
      <div className="flex items-center gap-3">
        <span className="shrink-0 text-tau-sm text-ink-3">动画进度</span>
        <div className="relative h-1.5 flex-1 rounded-full bg-track">
          <div className="h-full rounded-full bg-accent" style={{ width: `${progress * 100}%` }} />
        </div>
        <span className="w-24 shrink-0 text-right font-tau-mono text-tau-sm text-ink-2">
          {((progress * DURATION_MS) / 1000).toFixed(1)}s / {DURATION_MS / 1000}s
        </span>
      </div>
    </div>
  );
};
